import json
import re
from collections import defaultdict

def parse_plain_text_log(file_path):
    fault_patterns = {
        'ERROR': re.compile(r'ERROR', re.IGNORECASE),
        'WARNING': re.compile(r'WARNING', re.IGNORECASE),
        'CRITICAL': re.compile(r'CRITICAL', re.IGNORECASE),
    }
    faults = []
    with open(file_path, 'r') as f:
        for line in f:
            for fault_type, pattern in fault_patterns.items():
                if pattern.search(line):
                    faults.append((fault_type, line.strip()))
                    break
    return faults

def parse_json_log(file_path):
    faults = []
    with open(file_path, 'r') as f:
        try:
            logs = json.load(f)
            if isinstance(logs, dict):
                logs = [logs]
            for entry in logs:
                severity = entry.get('severity', '').upper()
                message = entry.get('message', '')
                if severity in ['ERROR', 'WARNING', 'CRITICAL']:
                    faults.append((severity, message))
        except json.JSONDecodeError:
            print(f"Error decoding JSON in file {file_path}")
    return faults

def categorize_faults(faults):
    fault_summary = defaultdict(lambda: {'count': 0, 'examples': []})
    for fault_type, message in faults:
        fault_summary[fault_type]['count'] += 1
        if len(fault_summary[fault_type]['examples']) < 5:
            fault_summary[fault_type]['examples'].append(message)
    return fault_summary

def generate_report(fault_summary):
    report_lines = []
    for fault_type, data in fault_summary.items():
        report_lines.append(f"Fault Type: {fault_type}")
        report_lines.append(f"Count: {data['count']}")
        report_lines.append("Examples:")
        for example in data['examples']:
            report_lines.append(f"  - {example}")
        report_lines.append("")
    return "\n".join(report_lines)

def diagnose_faults_from_logs(file_paths):
    all_faults = []
    for file_path in file_paths:
        if file_path.endswith('.json'):
            faults = parse_json_log(file_path)
        else:
            faults = parse_plain_text_log(file_path)
        all_faults.extend(faults)
    fault_summary = categorize_faults(all_faults)
    report = generate_report(fault_summary)
    return report

if __name__ == "__main__":
    import sys
    if len(sys.argv) < 2:
        print("Usage: python diagnose_faults.py <logfile1> [<logfile2> ...]")
        sys.exit(1)
    log_files = sys.argv[1:]
    report = diagnose_faults_from_logs(log_files)
    print(report)
```

