Here is a Python script that automates the inspection process of food safety logs stored in CSV format. The script will:

- Load the CSV file.
- Check for missing or invalid data.
- Validate temperature readings against safety thresholds.
- Check timestamps for consistency.
- Generate a summary report highlighting any issues found.

```python
import csv
from datetime import datetime

# Configuration: adjust these thresholds as needed
TEMPERATURE_MIN = 0    # Minimum safe temperature in Celsius
TEMPERATURE_MAX = 5    # Maximum safe temperature in Celsius
DATE_FORMAT = "%Y-%m-%d %H:%M:%S"  # Expected datetime format in logs

def load_csv(file_path):
    """Load CSV file and return list of dictionaries."""
    with open(file_path, mode='r', newline='', encoding='utf-8') as csvfile:
        reader = csv.DictReader(csvfile)
        data = list(reader)
    return data

def validate_temperature(temp_str):
    """Validate temperature is a float and within safe range."""
    try:
        temp = float(temp_str)
        if TEMPERATURE_MIN <= temp <= TEMPERATURE_MAX:
            return True, temp
        else:
            return False, temp
    except ValueError:
        return False, None

def validate_timestamp(timestamp_str):
    """Validate timestamp format."""
    try:
        timestamp = datetime.strptime(timestamp_str, DATE_FORMAT)
        return True, timestamp
    except ValueError:
        return False, None

def inspect_logs(data):
    """Inspect the food safety logs for issues."""
    issues = []
    previous_timestamp = None

    for idx, row in enumerate(data, start=1):
        row_issues = []
        # Check for missing fields
        if not row.get('Temperature'):
            row_issues.append("Missing temperature")
        if not row.get('Timestamp'):
            row_issues.append("Missing timestamp")

        # Validate temperature
        if 'Temperature' in row and row['Temperature']:
            valid_temp, temp_val = validate_temperature(row['Temperature'])
            if not valid_temp:
                if temp_val is None:
                    row_issues.append("Invalid temperature format")
                else:
                    row_issues.append(f"Temperature out of safe range: {temp_val}°C")

        # Validate timestamp
        if 'Timestamp' in row and row['Timestamp']:
            valid_time, timestamp_val = validate_timestamp(row['Timestamp'])
            if not valid_time:
                row_issues.append("Invalid timestamp format")
            else:
                # Check chronological order
                if previous_timestamp and timestamp_val < previous_timestamp:
                    row_issues.append("Timestamp out of order")
                previous_timestamp = timestamp_val

        if row_issues:
            issues.append({
                'Row': idx,
                'Issues': row_issues,
                'Data': row
            })

    return issues

def generate_report(issues):
    """Generate a summary report of the inspection."""
    if not issues:
        return "Inspection completed: No issues found in the food safety logs."

    report_lines = ["Inspection completed: Issues found in the food safety logs:\n"]
    for issue in issues:
        report_lines.append(f"Row {issue['Row']}:")
        for problem in issue['Issues']:
            report_lines.append(f"  - {problem}")
        report_lines.append(f"  Data: {issue['Data']}\n")

    return "\n".join(report_lines)

def main():
    file_path = 'food_safety_logs.csv'  # Change this to your CSV file path
    print(f"Loading data from {file_path}...")
    data = load_csv(file_path)

    print("Inspecting logs...")
    issues = inspect_logs(data)

    report = generate_report(issues)
    print(report)

if __name__ == "__main__":
    main()
```

