 * @param {FileList} files - The files selected by the user.
 * @param {string} uploadUrl - The server endpoint URL to upload files.
 * @returns {Promise<Array<string>>} - A promise that resolves to an array of public URLs.
 */
async function uploadFilesForSharing(files, uploadUrl) {
  if (!files || files.length === 0) {
    throw new Error('No files selected for upload.');
  }

  const uploadedUrls = [];

  for (const file of files) {
    const formData = new FormData();
    formData.append('file', file);

    try {
      const response = await fetch(uploadUrl, {
        method: 'POST',
        body: formData,
      });

      if (!response.ok) {
        throw new Error(`Failed to upload file: ${file.name}`);
      }

      const result = await response.json();

      // Assuming the server responds with { publicUrl: 'https://...' }
      if (result.publicUrl) {
        uploadedUrls.push(result.publicUrl);
      } else {
        throw new Error('Server did not return a public URL.');
      }
    } catch (error) {
      console.error(error);
      // Optionally, continue uploading other files or stop here
      throw error;
    }
  }

  return uploadedUrls;
}
