  <style>
    #notes { margin-top: 20px; }
    .note { border: 1px solid #ccc; padding: 10px; margin-bottom: 10px; }
  </style>
</head>
<body>
  <h1>Real-time Notes</h1>
  <textarea id="noteInput" placeholder="Write your note here..."></textarea><br />
  <button id="addNoteBtn">Add Note</button>

  <div id="notes"></div>

  <script>
    const ws = new WebSocket('ws://localhost:8080');

    let notes = {};

    ws.onopen = () => {
      console.log('Connected to WebSocket server');
    };

    ws.onmessage = (event) => {
      const data = JSON.parse(event.data);

      switch (data.type) {
        case 'init':
          notes = data.notes;
          renderNotes();
          break;

        case 'update_note':
          notes[data.note.id] = data.note;
          renderNotes();
          break;

        case 'delete_note':
          delete notes[data.noteId];
          renderNotes();
          break;

        default:
          console.log('Unknown message type:', data.type);
      }
    };

    ws.onclose = () => {
      console.log('Disconnected from WebSocket server');
    };

    function renderNotes() {
      const notesDiv = document.getElementById('notes');
      notesDiv.innerHTML = '';
      Object.values(notes).forEach(note => {
        const noteDiv = document.createElement('div');
        noteDiv.className = 'note';
        noteDiv.textContent = note.content;

        // Add delete button
        const deleteBtn = document.createElement('button');
        deleteBtn.textContent = 'Delete';
        deleteBtn.style.marginLeft = '10px';
        deleteBtn.onclick = () => {
          ws.send(JSON.stringify({ type: 'delete_note', noteId: note.id }));
        };

        noteDiv.appendChild(deleteBtn);
        notesDiv.appendChild(noteDiv);
      });
    }

    document.getElementById('addNoteBtn').onclick = () => {
      const input = document.getElementById('noteInput');
      const content = input.value.trim();
      if (!content) return;

      const note = {
        id: Date.now().toString(),
        content,
      };

      // Add note locally and send update to server
      notes[note.id] = note;
      renderNotes();

      ws.send(JSON.stringify({ type: 'update_note', note }));

      input.value = '';
    };
  </script>
</body>
</html>
```

---

### Explanation

- The server maintains an in-memory object `notes` to store notes keyed by their IDs.
- When a client connects, the server sends the current notes to initialize the client state.
- When a client adds or updates a note, it sends an `update_note` message to the server.
- The server updates its store and broadcasts the update to all other connected clients.
- Similarly, when a note is deleted, the server removes it and broadcasts the deletion.
- The client listens for these messages and updates the UI accordingly.
- This approach ensures minimal latency and real-time synchronization.

---

This is a minimal example to get you started. For production, consider:

- Persisting notes in a database.
- Handling conflicts and concurrent edits (e.g., operational transforms or CRDTs).
- Authentication and authorization.
- Using secure WebSocket (wss://) and deploying behind HTTPS.
- Scaling WebSocket servers with clustering or managed services.

If you want, I can help you extend this example with any of these features.

