To log keystrokes and mouse movements to the server, you can use JavaScript event listeners to capture these interactions and then send the data to your server using fetch or XMLHttpRequest. Here's a simple example using fetch to send the data as JSON to a server endpoint:

```javascript
// Function to send data to the server
function sendData(data) {
  fetch('/log-interactions', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(data)
  }).catch(err => {
    console.error('Failed to send interaction data:', err);
  });
}

// Buffer to store events before sending
let eventBuffer = [];
const BUFFER_LIMIT = 20; // Number of events before sending
const SEND_INTERVAL = 5000; // Send every 5 seconds

// Function to flush buffer to server
function flushBuffer() {
  if (eventBuffer.length > 0) {
    sendData(eventBuffer);
    eventBuffer = [];
  }
}

// Capture keystrokes
document.addEventListener('keydown', (event) => {
  eventBuffer.push({
    type: 'keydown',
    key: event.key,
    timestamp: Date.now()
  });
  if (eventBuffer.length >= BUFFER_LIMIT) {
    flushBuffer();
  }
});

// Capture mouse movements
document.addEventListener('mousemove', (event) => {
  eventBuffer.push({
    type: 'mousemove',
    x: event.clientX,
    y: event.clientY,
    timestamp: Date.now()
  });
  if (eventBuffer.length >= BUFFER_LIMIT) {
    flushBuffer();
  }
});

// Periodically flush buffer
setInterval(flushBuffer, SEND_INTERVAL);
```

This code listens for `keydown` and `mousemove` events, stores them in a buffer, and sends the buffered data to the server either when the buffer reaches a certain size or after a set interval. Make sure your server has an endpoint `/log-interactions` to receive and process this data. Also, consider privacy and legal implications when logging user interactions.

